-- Conformance fixtures: data definition. Re-authored minimal snippets (not copied from SAP docs).
-- Format: docs/specs/diagnostics/conformance-harness.md

-- @case column table with constraints
CREATE COLUMN TABLE departments (
  dept_id INTEGER NOT NULL PRIMARY KEY,
  dept_name NVARCHAR(100) NOT NULL,
  budget DECIMAL(15, 2) DEFAULT 0,
  loc_id INTEGER
);

-- @case row table with table-level constraints
CREATE ROW TABLE assignments (
  emp_id INTEGER,
  project_id INTEGER,
  share_pct TINYINT,
  PRIMARY KEY (emp_id, project_id),
  FOREIGN KEY (emp_id) REFERENCES employees (emp_id) ON DELETE CASCADE
);

-- @case identity and generated columns
CREATE COLUMN TABLE tickets (
  ticket_id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  opened TIMESTAMP,
  opened_day DATE GENERATED ALWAYS AS TO_DATE(opened)
);

-- @case unique column with index type
-- @todo syntax #78 false HANA-SYN-023 at "BTREE"
CREATE COLUMN TABLE codes (code_id INT PRIMARY KEY, code_key INT UNIQUE BTREE);

-- @case text column with fast preprocess
-- @todo syntax #78 false HANA-SYN-023 at "FAST", "OFF"
CREATE COLUMN TABLE documents (doc_id INT, body TEXT FAST PREPROCESS OFF);

-- @case hash partitioning
CREATE COLUMN TABLE events (event_id INT, region_id INT) PARTITION BY HASH (region_id) PARTITIONS 4;

-- @case range partitioning
CREATE COLUMN TABLE readings (reading_id INT, taken_year INT)
PARTITION BY RANGE (taken_year) (PARTITION 2020 <= VALUES < 2025, PARTITION OTHERS);

-- @case create table as select
CREATE COLUMN TABLE dept_copy AS (SELECT * FROM departments) WITH NO DATA;

-- @case create table like
CREATE COLUMN TABLE dept_shadow LIKE departments WITH DATA;

-- @case alter table add, alter and drop columns
-- @todo syntax #78 false HANA-SYN-023 at "NVARCHAR"
ALTER TABLE departments ADD (cost_center NVARCHAR(10));
ALTER TABLE departments ALTER (cost_center NVARCHAR(20));
ALTER TABLE departments DROP (cost_center);

-- @case alter table constraints
ALTER TABLE assignments ADD CONSTRAINT share_chk CHECK (share_pct BETWEEN 0 AND 100);
ALTER TABLE assignments DROP CONSTRAINT share_chk;

-- @case create and drop view
CREATE VIEW active_emps AS SELECT emp_id, last_name FROM employees WHERE active = 1;
DROP VIEW active_emps;

-- @case view with parameters
CREATE VIEW emps_by_dept (IN p_dept INTEGER) AS SELECT emp_id FROM employees WHERE dept_id = :p_dept;

-- @case view with column list, parameter defaults and comment
CREATE VIEW emp_names COMMENT 'employee names' (emp, name) (IN p_dept INTEGER, IN p_status NVARCHAR(10) DEFAULT 'ACTIVE')
AS SELECT emp_id, last_name FROM employees WHERE dept_id = :p_dept AND status = :p_status;

-- @case view and table with associations
CREATE VIEW emp_with_dept AS SELECT emp_id, dept_id FROM employees
WITH ASSOCIATIONS (JOIN departments AS dept ON dept.dept_id = dept_id, MANY TO ONE JOIN locations loc ON loc.loc_id = dept_id);
CREATE COLUMN TABLE assignments_assoc (emp_id INT, dept_id INT)
WITH ASSOCIATIONS (MANY TO ONE JOIN departments AS d ON d.dept_id = dept_id);

-- @case projection view with association
CREATE PROJECTION VIEW emp_projection AS SELECT emp_id, dept_id FROM employees
WITH ASSOCIATIONS (JOIN departments AS dept ON dept.dept_id = dept_id);

-- @case indexes
CREATE INDEX emp_name_idx ON employees (last_name, first_name);
CREATE UNIQUE INDEX emp_mail_idx ON employees (email);
DROP INDEX emp_name_idx;

-- @case sequence
CREATE SEQUENCE ticket_seq START WITH 100 INCREMENT BY 1 NO CYCLE;
SELECT ticket_seq.NEXTVAL FROM DUMMY;

-- @case schema and synonym
CREATE SCHEMA sales_area;
CREATE SYNONYM emp_syn FOR employees;
DROP SYNONYM emp_syn;

-- @case table type
CREATE TYPE emp_tt AS TABLE (emp_id INTEGER, last_name NVARCHAR(40));

-- @case comment on
COMMENT ON TABLE departments IS 'Organisational units';
COMMENT ON COLUMN departments.budget IS 'Yearly budget';

-- @case rename and drop table
RENAME TABLE dept_copy TO dept_backup;
DROP TABLE dept_backup CASCADE;

-- @case trigger
CREATE TRIGGER emp_audit AFTER UPDATE ON employees REFERENCING NEW ROW new_row FOR EACH ROW
BEGIN
  INSERT INTO emp_log VALUES (:new_row.emp_id, CURRENT_TIMESTAMP);
END;

-- @case structured filter with a condition provider [CLOUD]
CREATE STRUCTURED FILTER sales_filter FOR SELECT ON sales_view CONDITION PROVIDER sales_filter_provider;

-- @case structured filter with a static condition on two views [CLOUD]
CREATE STRUCTURED FILTER region_filter FOR SELECT ON sales_view, orders_view WHERE region = SESSION_CONTEXT('REGION');
